#!/usr/bin/env python3
"""Turns clean + patched ntdll.dll pairs into NtdllRecipes.swift (byte-diff recipes).

usage: make-recipes.py <engine lib/wine dir> <patched dir with <arch>/ntdll.dll> > NtdllRecipes.swift
"""
import hashlib
import sys

eng, pat = sys.argv[1], sys.argv[2]
out = [
    "// Generated by tools/steamplay/gen/make-recipes.py. Do not edit by hand.",
    "// Each recipe turns the engine's clean ntdll.dll into the patched copy (NotProton's GPL-3.0 detour,",
    "// rebuilt by Decant for this engine) that sends games' Steam API calls to Mac Steam via lsteamclient.",
    "enum NtdllRecipes {",
    "    static let all: [NtdllRecipe] = [",
]
for arch in ("x86_64-windows", "i386-windows"):
    a = open(f"{eng}/{arch}/ntdll.dll", "rb").read()
    b = open(f"{pat}/{arch}/ntdll.dll", "rb").read()
    a_pad = a + b"\0" * max(0, len(b) - len(a))
    runs = []
    i = 0
    while i < len(b):
        if b[i] != a_pad[i] or i >= len(a):
            j = i
            while j < len(b) and (b[j] != a_pad[j] or j >= len(a)):
                j += 1
            runs.append([i, j])
            i = j
        else:
            i += 1
    merged = []
    for s, e in runs:
        if merged and s - merged[-1][1] < 16:
            merged[-1][1] = e
        else:
            merged.append([s, e])
    out += [
        "        NtdllRecipe(",
        f'            arch: "{arch}",',
        f'            cleanSHA256: "{hashlib.sha256(a).hexdigest()}",',
        f'            patchedSHA256: "{hashlib.sha256(b).hexdigest()}",',
        f"            patchedSize: {len(b)},",
        "            writes: [",
    ]
    for s, e in merged:
        out.append(f'                .init(offset: {s:#x}, hex: "{b[s:e].hex()}"),')
    out += ["            ]", "        ),"]
    print(f"{arch}: {len(merged)} writes, {sum(e - s for s, e in merged)} bytes, size {len(a)} -> {len(b)}", file=sys.stderr)
out += ["    ]", "}"]
print("\n".join(out))
